inline int read()
{
	int x=0,w=1;
	char c=getchar();
	while (!isdigit(c)&&c!='-') c=getchar();
	if (c=='-') c=getchar(),w=-1;
	while (isdigit(c))
	{
		x=(x<<1)+(x<<3)+c-'0';
		c=getchar();
	}
	return x*w;
}
inline void add_edge(int from,int to)
{
	edge[++num]=(node){to,head[from]};
	head[from]=num;
}
void dfs(int k,int fa)
{
	dep[k]=dep[fa]+1; tot[k]=1;
	for (reg int i=head[k];i;i=edge[i].nxt)
	{
		int v=edge[i].to;
		if (v==fa) continue;
		dfs(v,k); tot[k]+=tot[v];
	}
}
int main()
{
	n=read();
	for (reg int i=1;i<n;i++)
	{
		int x=read(),y=read();
		add_edge(x,y); add_edge(y,x);
	}
	dfs(1,0);
	for (reg int i=1;i<=n;i++)
	{
		ans+=1ll*tot[i]*(n-tot[i]);
		if (dep[i]&1) ++cnt;
	}
